SELECT scope_type, COUNT(DISTINCT promotion_id) AS promotion_count
FROM agent_v3_promotion_offer_view WHERE agent_v3_promotion_offer_view.store_id = ANY(:allowedStoreIds) GROUP BY scope_type
LIMIT 100;

SELECT level_name
FROM agent_v3_staff_profile_view WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) GROUP BY level_name
LIMIT 100;

SELECT COUNT(DISTINCT transfer_id) AS transfer_count
FROM ask_data_transfer_status_view
WHERE ask_data_transfer_status_view.store_id = ANY(:allowedStoreIds) AND (status IN ('***', '***', '***')) LIMIT 1;
